// Global mock database
export interface Post {
  id: string;
  title: string;
  content: string;
}

// In-memory store (will reset on server restart, but works for dev demo)
// Using global to persist across hot reloads in dev if possible, though module-level variable might be cleared.
// For a robust demo, we might use a file, but let's stick to simple first.
const globalFordb = global as unknown as { posts: Post[] };

export const db = {
  posts: globalFordb.posts || [
    { id: '1', title: 'First Post', content: 'Hello world!' },
  ],
  async findMany() {
    // Simulate network delay
    await new Promise((resolve) => setTimeout(resolve, 100));
    return [...this.posts];
  },
  async create(data: Omit<Post, 'id'>) {
    // Simulate network delay
    await new Promise((resolve) => setTimeout(resolve, 100));
    const newPost = { id: Date.now().toString(), ...data };
    this.posts.push(newPost);
    if (!globalFordb.posts) globalFordb.posts = this.posts;
    return newPost;
  },
};

