'use server'

import { revalidateTag } from 'next/cache'
import { db } from '@/app/lib/db'
import { redirect } from 'next/navigation'

export async function createPost(formData: FormData) {
  const title = formData.get('title')
  const content = formData.get('content')

  if (typeof title !== 'string' || typeof content !== 'string' || !title || !content) {
    throw new Error('Title and content are required')
  }

  try {
    // Create the post in the database
    await db.create({ title, content })

    // Invalidate the cache for the 'posts' tag.
    // This ensures that any data fetched with this tag is purged from the cache,
    // and the next request will fetch fresh data from the source.
    revalidateTag('posts')
  } catch (error) {
    console.error('Failed to create post:', error)
    throw new Error('Failed to create post')
  }

  // Navigate back to home or refresh the current route implicitly
  redirect('/')
}

