import { unstable_cache } from 'next/cache';
import { db } from './lib/db';
import { createPost } from './actions';

// This uses Next.js 'unstable_cache' which allows setting cache tags.
// When 'posts' tag is revalidated, this cache entry is cleared.
const getPosts = unstable_cache(
  async () => {
    return db.findMany();
  },
  ['posts-list-key'], // Unique key for this cache entry
  { tags: ['posts'] } // Cache tag used for invalidation
);

export default async function Home() {
  const posts = await getPosts();

  return (
    <main style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h1>Posts</h1>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {posts.map((post) => (
          <li key={post.id} style={{ border: '1px solid #ccc', padding: '10px', marginBottom: '10px', borderRadius: '4px' }}>
            <h2 style={{ margin: '0 0 10px 0' }}>{post.title}</h2>
            <p style={{ margin: 0 }}>{post.content}</p>
          </li>
        ))}
      </ul>

      <hr style={{ margin: '20px 0' }} />

      <h2>Create New Post</h2>
      <form action={createPost} style={{ display: 'flex', flexDirection: 'column', gap: '10px', maxWidth: '400px' }}>
        <div style={{ display: 'flex', flexDirection: 'column' }}>
          <label htmlFor="title" style={{ marginBottom: '5px' }}>Title</label>
          <input type="text" id="title" name="title" required style={{ padding: '8px', border: '1px solid #ccc', borderRadius: '4px' }} />
        </div>
        <div style={{ display: 'flex', flexDirection: 'column' }}>
          <label htmlFor="content" style={{ marginBottom: '5px' }}>Content</label>
          <textarea id="content" name="content" required style={{ padding: '8px', border: '1px solid #ccc', borderRadius: '4px', minHeight: '100px' }} />
        </div>
        <button type="submit" style={{ padding: '10px', backgroundColor: '#0070f3', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>
          Create Post
        </button>
      </form>
    </main>
  );
}

